## Why This Is Asked
This problem evaluates the ability to design a practical dynamic sequence with non-trivial frequency queries—a common requirement in analytics and data processing systems.

## Key Concepts
- **Sqrt decomposition** for dynamic sequences partitions data into blocks of approximately √n elements
- **Per-block frequency maps** enable O(√n) rangeFreq queries
- **Block maintenance**: splits when blocks overflow and merges when they underflow to maintain balance
- **Edge handling**: properly handles partial blocks during queries and updates

## Code Example
```javascript
class Block {
  constructor() {
    this.values = [];
    this.freq = new Map();
  }

  rebuild() {
    this.freq.clear();
    for (const v of this.values) {
      this.freq.set(v, (this.freq.get(v) || 0) + 1);
    }
  }
}

class DynamicSequence {
  constructor() {
    this.blocks = [];
    this.B = Math.ceil(Math.sqrt(10));
  }

  locate(index) {
    let offset = 0;
    for (const block of this.blocks) {
      if (offset + block.values.length > index) {
        return { block, pos: index - offset };
      }
      offset += block.values.length;
    }
  }

  append(value) {
    if (this.blocks.length === 0) this.blocks.push(new Block());
    const last = this.blocks[this.blocks.length - 1];
    last.values.push(value);
    last.freq.set(value, (last.freq.get(value) || 0) + 1);
    if (last.values.length > 2 * this.B) this.split(last);
  }

  split(block) {
    const mid = Math.floor(block.values.length / 2);
    const newBlock = new Block();
    newBlock.values = block.values.splice(mid);
    block.rebuild();
    newBlock.rebuild();
    this.blocks.push(newBlock);
  }

  rangeFreq(l, r, value) {
    let count = 0;
    const { block: startBlock, pos: startPos } = this.locate(l);
    const { block: endBlock, pos: endPos } = this.locate(r);

    if (startBlock === endBlock) {
      for (let i = startPos; i <= endPos; i++) {
        if (startBlock.values[i] === value) count++;
      }
      return count;
    }

    for (let i = startPos; i < startBlock.values.length; i++) {
      if (startBlock.values[i] === value) count++;
    }
    for (const block of this.blocks) {
      if (block === startBlock || block === endBlock) continue;
      count += block.freq.get(value) || 0;
    }
    for (let i = 0; i <= endPos; i++) {
      if (endBlock.values[i] === value) count++;
    }
    return count;
  }
}
```

## Why This Is Asked
Assesses practical use of an augmented BST (treap) to support ranking with duplicates in a live leaderboard setting.

## Key Concepts
- Treap with random priorities for balancing
- Node augmentation: subtree size for rank queries
- Key design: (score, playerId) to distinguish duplicates
- Rank query logic traversing by score threshold
- Handling time-evolving duplicates safely

## Code Example
```javascript
class LeaderboardTreap {
  constructor() { this.root = null; }
  _cmp(a, b) {
    if (a.score !== b.score) return a.score - b.score;
    return a.playerId.localeCompare(b.playerId);
  }
  _size(n) { return n ? n.size : 0; }
  _update(n) { if (n) n.size = 1 + this._size(n.left) + this._size(n.right); }
  _rotateLeft(p) {
    const r = p.right; p.right = r.left; r.left = p; this._update(p); this._update(r); return r;
  }
  _rotateRight(p) {
    const l = p.left; p.left = l.right; l.right = p; this._update(p); this._update(l); return l;
  }
  insertScore(playerId, score) {
    const key = { playerId, score, __prio: Math.random() };
    this.root = this._insert(this.root, key);
  }
  _insert(n, key) {
    if (!n) return { key, priority: key.__prio, left: null, right: null, size: 1 };
    if (this._cmp(key, n.key) < 0) {
      n.left = this._insert(n.left, key);
      if (n.left.priority > n.priority) n = this._rotateRight(n);
    } else {
      n.right = this._insert(n.right, key);
      if (n.right.priority > n.priority) n = this._rotateLeft(n);
    }
    this._update(n); return n;
  }
  eraseScore(playerId, score) {
    const key = { playerId, score };
    this.root = this._erase(this.root, key);
  }
  _erase(n, key) {
    if (!n) return null;
    const c = this._cmp(key, n.key);
    if (c < 0) { n.left = this._erase(n.left, key); }
    else if (c > 0) { n.right = this._erase(n.right, key); }
    else {
      if (!n.left) return n.right;
      if (!n.right) return n.left;
      if (n.left.priority > n.right.priority) { n = this._rotateRight(n); n.right = this._erase(n.right, key); }
      else { n = this._rotateLeft(n); n.left = this._erase(n.left, key); }
    }
    this._update(n); return n;
  }
  getRank(score) {
    const dfs = (n) => {
      if (!n) return 0;
      if (n.key.score <= score) return this._size(n.left) + 1 + dfs(n.right);
      return dfs(n.left);
    };
    return dfs(this.root);
  }
}
```

